#!/usr/bin/env python3
"""Build one self-contained HTML mockup for the demo and main experiment."""

import json
import sys
from datetime import date
from pathlib import Path


PROJECT = Path(__file__).resolve().parent.parent
OUT = Path(__file__).resolve().parent / "Candidate_Recruiter_Experiment_Mockup.html"
SCENARIO_DIR = PROJECT / "app" / "config"
PRACTICE_FILE = SCENARIO_DIR / "tutorial.json"
sys.path.insert(0, str(PROJECT / 'app/backend'))
sys.path.insert(0, str(PROJECT / 'developer'))
from scenario_rules import is_fixed, private_payoff_rows
from role_presentation import role_narrative, narrative_to_html


def load_scenarios() -> dict:
    payload = {}
    for key, filename in (("small", "small-15.json"), ("large", "large-215.json"), ("fixed", "fixed-15.json")):
        scenario = json.loads((SCENARIO_DIR / filename).read_text(encoding="utf-8"))
        policy = {"small": "bounded", "large": "open", "fixed": "fixed"}[key]
        payload[key] = {
            "label": scenario['scenario_variant']['label'],
            "scenario_id": scenario.get("scenario_id"),
            "material_revision": scenario.get("material_revision"),
            "variant_id": scenario['scenario_variant']['id'],
            "required_issues": scenario['required_issues'],
            "summaries": {role: scenario['roles'][role]['summary'] for role in ('Candidate', 'Recruiter')},
            "private_tables": {role: private_payoff_rows(scenario, role) for role in ('Candidate', 'Recruiter')} if is_fixed(scenario) else {},
            "issue_count": len(scenario.get("issues", [])),
            "agreement_bonus_cap_usd": scenario.get("payment", {}).get("agreement_bonus_cap_usd"),
            # This trusted HTML is generated from the scenario's structured
            # role blocks. The feedback survey uses the same presentation
            # functions, so visual changes cannot drift between prototypes.
            "role_html": {
                role: narrative_to_html(role_narrative(scenario["roles"][role]["full_blocks"], policy=policy))
                for role in ("Candidate", "Recruiter")
            },
        }
    return payload


def build() -> Path:
    scenarios = load_scenarios()
    scenario_json = json.dumps(scenarios, ensure_ascii=False).replace("</", "<\\/")
    practice = json.loads(PRACTICE_FILE.read_text(encoding="utf-8"))
    practice["participant_role"] = practice["practice"]["participant_role"]
    practice["counterpart_role"] = practice["practice"]["counterpart_role"]
    practice["predetermined_replies"] = practice["practice"]["predetermined_replies"]
    practice["participant_material"] = {
        "opening": practice["roles"]["Candidate"]["summary"],
        "additional_information": practice["roles"]["Candidate"]["full_text"],
    }
    practice_json = json.dumps(practice, ensure_ascii=False).replace("</", "<\\/")
    content = (
        TEMPLATE.replace("__SCENARIO_JSON__", scenario_json)
        .replace("__PRACTICE_JSON__", practice_json)
        .replace("__BUILD_DATE__", date.today().isoformat())
    )
    OUT.write_text(content, encoding="utf-8")
    return OUT


